CREATE TABLE log_content (
    log_id INT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    content VARCHAR(32) NOT NULL,
    PRIMARY KEY (log_id)
);

-- Step 2: Create a trigger function
CREATE OR REPLACE FUNCTION update_no_of_chars()
RETURNS TRIGGER AS $$
BEGIN
    NEW.no_of_chars := LENGTH(NEW.content);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Step 3: Create a trigger that calls the trigger function on insert
CREATE TRIGGER trg_update_no_of_chars
BEFORE INSERT ON log_content
FOR EACH ROW
EXECUTE FUNCTION update_no_of_chars();

